type JsonPrimitive = string | number | boolean | null;
type JsonValue = JsonPrimitive | JsonValue[] | { [key: string]: JsonValue };
type JsonObject = { [key: string]: JsonValue };

import { findClosestFingerprint, xpathFor } from "./element-finder";
import { executeContentAction } from "./actions";
import { shouldAttachStateSnapshot } from "./snapshots";

type RectDescriptor = { x: number; y: number; width: number; height: number };
type DomElementDescriptor = {
  tagName: string;
  selector: string;
  xpath?: string | undefined;
  id?: string | undefined;
  classNames?: string[] | undefined;
  visibleText?: string | undefined;
  text?: string | undefined;
  value?: string | undefined;
  role?: string | undefined;
  name?: string | undefined;
  href?: string | undefined;
  inputType?: string | undefined;
  bounds?: RectDescriptor | undefined;
  documentBounds?: RectDescriptor | undefined;
  isVisibleOnViewport?: boolean | undefined;
  hasClickHandler?: boolean | undefined;
  attributes?: Record<string, string> | undefined;
};
type DomSnapshot = {
  url: string;
  title: string;
  viewport: { width: number; height: number; scrollX: number; scrollY: number; documentWidth?: number | undefined; documentHeight?: number | undefined; devicePixelRatio?: number | undefined };
  frame?: FrameDescriptor | undefined;
  focusedElement?: DomElementDescriptor | undefined;
  selectedText?: string | undefined;
  interactiveElements: DomElementDescriptor[];
};
type FrameDescriptor = {
  isTop: boolean;
  viewportOffset?: RectDescriptor | undefined;
};
type RecordingEventPayload = {
  kind: string;
  sequence: number;
  url: string;
  title: string;
  eventTimestampMs: number;
  element?: DomElementDescriptor | undefined;
  snapshot?: DomSnapshot | undefined;
  inputValue?: string | undefined;
  key?: string | undefined;
  scroll?: { x: number; y: number } | undefined;
  mutation?: { added: number; removed: number; attributes: number; text: number } | undefined;
  actionResult?: BrowserActionResult | undefined;
  metadata?: JsonObject | undefined;
};
type BrowserActionCommand = {
  commandId: string;
  actionType: string;
  selector?: string | undefined;
  text?: string | undefined;
  value?: string | undefined;
  key?: string | undefined;
  timeoutMs?: number | undefined;
  coordinates?: { x: number; y: number } | undefined;
  visualTarget?: {
    bounds?: RectDescriptor | undefined;
    documentBounds?: RectDescriptor | undefined;
    anchor?: { type: "bounds"; bounds: RectDescriptor } | undefined;
    selector?: string | undefined;
  } | undefined;
  options?: JsonObject | undefined;
};
type BrowserActionResult = {
  commandId: string;
  actionType: string;
  status: "succeeded" | "failed" | "timed_out" | "cancelled";
  message?: string | undefined;
  url?: string | undefined;
  title?: string | undefined;
  element?: DomElementDescriptor | undefined;
  visualTarget?: BrowserActionCommand["visualTarget"] | undefined;
  snapshot?: DomSnapshot | undefined;
  extracted?: JsonValue | undefined;
  startedAt: number;
  finishedAt: number;
};

const CONTENT_EVENT = "fluxiq.contentEvent";
const CONTENT_READY = "fluxiq.contentReady";
const FRAME_GEOMETRY_REQUEST = "fluxiq.frameGeometryRequest";
const FRAME_GEOMETRY_RESPONSE = "fluxiq.frameGeometryResponse";
const MAX_SNAPSHOT_CANDIDATES = 2_000;
const MAX_SNAPSHOT_SCAN_ELEMENTS = 50_000;
const ACTIVE_CONTENT_INSTANCE_KEY = "__fluxiqWebAutomationActiveContentInstance";
const CONTENT_SCRIPT_VERSION = 2;
const MAX_OBSERVED_EVENT_ELEMENTS = 500;
const CONTENT_INSTANCE_ID = `${Date.now()}.${Math.random().toString(36).slice(2)}`;
const contentWindow = window as Window & { [ACTIVE_CONTENT_INSTANCE_KEY]?: string };
contentWindow[ACTIVE_CONTENT_INSTANCE_KEY] = CONTENT_INSTANCE_ID;
let recording = false;
let sequence = 0;
let captureMutations = true;
let captureInputValues = true;
let captureSnapshots = true;
let scrollTimer: ReturnType<typeof setTimeout> | undefined;
let mutationTimer: ReturnType<typeof setTimeout> | undefined;
let inputTimer: ReturnType<typeof setTimeout> | undefined;
let pendingInput: { element: Element; inputValue?: string | undefined } | undefined;
let pendingMutation = { added: 0, removed: 0, attributes: 0, text: 0 };
const observedEventElements = new WeakSet<Element>();
const observedEventElementQueue: Element[] = [];
let frameViewportOffset: RectDescriptor | undefined = isTopFrame()
  ? { x: 0, y: 0, width: window.innerWidth, height: window.innerHeight }
  : undefined;
let frameGeometryRequestId = 0;

sendReady();
installFrameGeometryBridge();

chrome.runtime.onMessage.addListener((message: unknown, _sender, sendResponse) => {
  const typed = message as { type?: string; recording?: boolean; settings?: { captureMutations?: boolean; captureInputValues?: boolean; captureSnapshots?: boolean }; action?: BrowserActionCommand; commandId?: string; x?: number; y?: number; topFrameOnly?: boolean };
  if (typed.type === "fluxiq.ping") {
    sendResponse({ ok: true, active: isActiveContentInstance(), version: CONTENT_SCRIPT_VERSION });
    return false;
  }
  if (!isActiveContentInstance()) return false;
  if (typed.type === "recording") {
    captureMutations = typed.settings?.captureMutations ?? captureMutations;
    captureInputValues = typed.settings?.captureInputValues ?? captureInputValues;
    captureSnapshots = typed.settings?.captureSnapshots ?? captureSnapshots;
    setRecordingState(Boolean(typed.recording));
    sendResponse({ ok: true });
    return true;
  }
  if (typed.type === "captureSnapshot") {
    void captureSnapshotForResponse().then(sendResponse);
    return true;
  }
  if (typed.type === "executeAction" && typed.action) {
    if (typed.topFrameOnly === true && !isTopFrame()) return false;
    void executeAction(typed.action)
      .then(sendResponse)
      .catch((error: unknown) => sendResponse(actionFailure(typed.action as BrowserActionCommand, error)));
    return true;
  }
  return false;
});

document.addEventListener("pointerdown", (event) => {
  if (!recording) return;
  if (!event.isTrusted) return;
  if (event.button !== 0 || event.isPrimary === false) return;
  rememberEventPathElements(event);
  const eventElement = eventTargetElement(event);
  const target = eventElement ? pointerActivationTarget(eventElement) : null;
  if (!target) return;
  emit("dom.click", compactObject({
    element: describeElement(target),
    metadata: compactObject({
      ...pointerMetadata(event),
      pointerId: event.pointerId,
      pointerType: event.pointerType,
      sourceEvent: "pointerdown",
      captureTiming: "before-action"
    })
  }));
}, true);

document.addEventListener("click", (event) => {
  if (!recording) return;
  if (!event.isTrusted) return;
  rememberEventPathElements(event);
  const eventElement = eventTargetElement(event);
  const target = eventElement ? actionEventTarget(eventElement) : null;
  emit("dom.click", compactObject({
    element: target ? describeElement(target) : undefined,
    metadata: compactObject({
      ...pointerMetadata(event),
      sourceEvent: "click"
    })
  }));
}, true);

document.addEventListener("input", (event) => {
  if (!recording) return;
  rememberEventPathElements(event);
  const target = event.target instanceof Element ? event.target : null;
  if (target && isTextEntryElement(target)) {
    scheduleInputEvent(target);
    return;
  }
  emitInputEvent(target);
}, true);

document.addEventListener("change", (event) => {
  if (!recording) return;
  rememberEventPathElements(event);
  const target = event.target instanceof Element ? event.target : null;
  if (target && isTextEntryElement(target)) {
    flushPendingInput();
    return;
  }
  if (target && !shouldRecordChangeEvent(target)) return;
  emit("dom.change", compactObject({
    element: target ? describeElement(target) : undefined,
    inputValue: captureInputValues ? readElementValue(target) : undefined
  }));
}, true);

document.addEventListener("submit", (event) => {
  if (!recording) return;
  rememberEventPathElements(event);
  const target = event.target instanceof Element ? event.target : null;
  emit("dom.submit", compactObject({ element: target ? describeElement(target) : undefined }));
}, true);

document.addEventListener("keydown", (event) => {
  if (!recording) return;
  if (!event.isTrusted) return;
  rememberEventPathElements(event);
  emit("dom.keydown", compactObject({
    key: event.key,
    element: event.target instanceof Element ? describeElement(event.target) : undefined,
    metadata: {
      altKey: event.altKey,
      ctrlKey: event.ctrlKey,
      metaKey: event.metaKey,
      shiftKey: event.shiftKey
    }
  }));
}, true);

document.addEventListener("wheel", (event) => {
  if (!recording) return;
  if (!event.isTrusted) return;
  if (scrollTimer) clearTimeout(scrollTimer);
  scrollTimer = setTimeout(() => {
    emit("dom.scroll", {
      scroll: { x: window.scrollX, y: window.scrollY },
      metadata: {
        sourceEvent: "wheel",
        deltaX: event.deltaX,
        deltaY: event.deltaY,
        deltaZ: event.deltaZ,
        deltaMode: event.deltaMode,
        altKey: event.altKey,
        ctrlKey: event.ctrlKey,
        metaKey: event.metaKey,
        shiftKey: event.shiftKey
      }
    });
  }, 400);
}, true);

window.addEventListener("scroll", () => {
  if (!recording) return;
  if (scrollTimer) clearTimeout(scrollTimer);
  scrollTimer = setTimeout(() => {
    emit("dom.scroll", { scroll: { x: window.scrollX, y: window.scrollY } });
  }, 400);
}, true);

const observer = new MutationObserver((mutations) => {
  if (!captureMutations || !recording) return;
  for (const mutation of mutations) {
    pendingMutation.added += mutation.addedNodes.length;
    pendingMutation.removed += mutation.removedNodes.length;
    if (mutation.type === "attributes") pendingMutation.attributes += 1;
    if (mutation.type === "characterData") pendingMutation.text += 1;
  }
  if (mutationTimer) clearTimeout(mutationTimer);
  mutationTimer = setTimeout(() => {
    emit("dom.mutation", { mutation: pendingMutation });
    pendingMutation = { added: 0, removed: 0, attributes: 0, text: 0 };
  }, 500);
});

function sendReady(): void {
  if (!isActiveContentInstance()) return;
  const payload = basePayload("content.ready", {
    metadata: { readyState: document.readyState }
  });
  void chrome.runtime.sendMessage({ type: CONTENT_READY, payload });
}

async function captureSnapshotForResponse(): Promise<DomSnapshot> {
  if (!isTopFrame()) await requestFrameGeometry();
  return captureSnapshot();
}

function emit(kind: string, details: Partial<RecordingEventPayload>): void {
  if (!isActiveContentInstance()) return;
  if (!recording && kind !== "content.ready") return;
  const payload = basePayload(kind, details);
  void chrome.runtime.sendMessage({ type: CONTENT_EVENT, payload });
}

function isActiveContentInstance(): boolean {
  return contentWindow[ACTIVE_CONTENT_INSTANCE_KEY] === CONTENT_INSTANCE_ID;
}

function installFrameGeometryBridge(): void {
  window.addEventListener("message", (event) => {
    const data = event.data as { type?: string; requestId?: unknown; geometry?: unknown } | undefined;
    if (!data || typeof data !== "object") return;
    if (data.type === FRAME_GEOMETRY_REQUEST) {
      const requestId = typeof data.requestId === "number" ? data.requestId : undefined;
      const geometry = childFrameViewportOffset(event.source);
      if (!geometry || !event.source || typeof event.source.postMessage !== "function") return;
      (event.source.postMessage as (message: unknown, targetOrigin: string) => void)({
        type: FRAME_GEOMETRY_RESPONSE,
        requestId,
        geometry
      }, "*");
      return;
    }
    if (data.type === FRAME_GEOMETRY_RESPONSE) {
      const geometry = rectFromUnknown(data.geometry);
      if (geometry) frameViewportOffset = geometry;
    }
  });
  window.addEventListener("resize", () => {
    if (isTopFrame()) frameViewportOffset = { x: 0, y: 0, width: window.innerWidth, height: window.innerHeight };
    else void requestFrameGeometry();
  }, true);
  window.addEventListener("scroll", () => {
    if (!isTopFrame()) void requestFrameGeometry();
  }, true);
}

function requestFrameGeometry(): Promise<RectDescriptor | undefined> {
  if (isTopFrame()) {
    frameViewportOffset = { x: 0, y: 0, width: window.innerWidth, height: window.innerHeight };
    return Promise.resolve(frameViewportOffset);
  }
  const requestId = ++frameGeometryRequestId;
  return new Promise((resolve) => {
    const timeout = setTimeout(() => resolve(frameViewportOffset), 75);
    const listener = (event: MessageEvent) => {
      const data = event.data as { type?: string; requestId?: unknown; geometry?: unknown } | undefined;
      if (!data || data.type !== FRAME_GEOMETRY_RESPONSE || data.requestId !== requestId) return;
      const geometry = rectFromUnknown(data.geometry);
      if (geometry) frameViewportOffset = geometry;
      clearTimeout(timeout);
      window.removeEventListener("message", listener);
      resolve(frameViewportOffset);
    };
    window.addEventListener("message", listener);
    window.parent.postMessage({ type: FRAME_GEOMETRY_REQUEST, requestId }, "*");
  });
}

function childFrameViewportOffset(source: MessageEventSource | null): RectDescriptor | undefined {
  if (!source) return undefined;
  const frameElement = [...document.querySelectorAll("iframe,frame")]
    .find((element): element is HTMLIFrameElement | HTMLFrameElement =>
      (element instanceof HTMLIFrameElement || element instanceof HTMLFrameElement) &&
      element.contentWindow === source
    );
  if (!frameElement) return undefined;
  const rect = frameElement.getBoundingClientRect();
  const parentOffset = currentFrameViewportOffset() ?? { x: 0, y: 0, width: window.innerWidth, height: window.innerHeight };
  return {
    x: Math.round((parentOffset.x + rect.left) * 100) / 100,
    y: Math.round((parentOffset.y + rect.top) * 100) / 100,
    width: Math.round(rect.width * 100) / 100,
    height: Math.round(rect.height * 100) / 100
  };
}

function currentFrameViewportOffset(): RectDescriptor | undefined {
  if (isTopFrame()) return { x: 0, y: 0, width: window.innerWidth, height: window.innerHeight };
  return frameViewportOffset;
}

function isTopFrame(): boolean {
  return window.top === window;
}

function rectFromUnknown(value: unknown): RectDescriptor | undefined {
  if (!value || typeof value !== "object") return undefined;
  const rect = value as { x?: unknown; y?: unknown; width?: unknown; height?: unknown };
  return typeof rect.x === "number" &&
    typeof rect.y === "number" &&
    typeof rect.width === "number" &&
    typeof rect.height === "number"
    ? { x: rect.x, y: rect.y, width: rect.width, height: rect.height }
    : undefined;
}

function setRecordingState(nextRecording: boolean): void {
  if (!nextRecording) flushPendingInput();
  recording = nextRecording;
  if (recording && captureMutations) {
    observer.observe(document.documentElement, {
      childList: true,
      subtree: true,
      attributes: true,
      characterData: true
    });
  } else {
    observer.disconnect();
    if (mutationTimer) clearTimeout(mutationTimer);
    mutationTimer = undefined;
    pendingMutation = { added: 0, removed: 0, attributes: 0, text: 0 };
  }
}

function scheduleInputEvent(element: Element): void {
  pendingInput = { element, inputValue: captureInputValues ? readElementValue(element) : undefined };
  if (inputTimer) clearTimeout(inputTimer);
  inputTimer = setTimeout(() => flushPendingInput(), 350);
}

function flushPendingInput(): void {
  if (inputTimer) clearTimeout(inputTimer);
  inputTimer = undefined;
  const pending = pendingInput;
  pendingInput = undefined;
  if (!pending) return;
  emit("dom.input", compactObject({
    element: describeElement(pending.element),
    inputValue: pending.inputValue
  }));
}

function emitInputEvent(element: Element | null): void {
  emit("dom.input", compactObject({
    element: element ? describeElement(element) : undefined,
    inputValue: captureInputValues ? readElementValue(element) : undefined
  }));
}

function basePayload(kind: string, details: Partial<RecordingEventPayload>): RecordingEventPayload {
  const payload: RecordingEventPayload = {
    kind,
    sequence: ++sequence,
    url: location.href,
    title: document.title,
    eventTimestampMs: Date.now()
  };
  if (details.element) payload.element = details.element;
  if (captureSnapshots) {
    const snapshot = details.snapshot ?? (shouldAttachStateSnapshot(kind) ? captureSnapshot() : undefined);
    if (snapshot) payload.snapshot = snapshot;
  }
  if (details.inputValue !== undefined) payload.inputValue = details.inputValue;
  if (details.key !== undefined) payload.key = details.key;
  if (details.scroll) payload.scroll = details.scroll;
  if (details.mutation) payload.mutation = details.mutation;
  if (details.actionResult) payload.actionResult = details.actionResult;
  if (details.metadata) payload.metadata = details.metadata;
  return payload;
}

async function executeAction(action: BrowserActionCommand): Promise<BrowserActionResult> {
  return executeContentAction(action, {
    captureSnapshot,
    resolveTarget,
    describeElement,
    waitForElement,
    waitForText,
    extractElement,
    scrollElementIntoView,
    setElementValue,
    dispatchInputEvents,
    success,
    failure: actionFailure
  });
}

function resolveTarget(action: BrowserActionCommand): Element {
  const misses: string[] = [];
  if (action.selector) {
    const element = document.querySelector(action.selector);
    if (element) return element;
    misses.push(`selector ${action.selector}`);
  }
  if (action.coordinates) {
    const element = document.elementFromPoint(action.coordinates.x, action.coordinates.y);
    if (element) return element;
    misses.push(`coordinates ${action.coordinates.x},${action.coordinates.y}`);
  }
  const visualPoint = pointFromVisualTarget(action.visualTarget);
  if (visualPoint) {
    const element = document.elementFromPoint(visualPoint.x, visualPoint.y);
    if (element) return element;
    misses.push(`visual target ${Math.round(visualPoint.x)},${Math.round(visualPoint.y)}`);
  }
  const fingerprint = action.options?.element;
  if (fingerprint && typeof fingerprint === "object" && !Array.isArray(fingerprint)) {
    const element = findClosestFingerprint(fingerprint as Parameters<typeof findClosestFingerprint>[0]);
    if (element) return element;
    misses.push("element fingerprint");
  }
  if (!misses.length) {
    const active = document.activeElement;
    if (active) return active;
  }
  if (misses.length) throw new Error(`No target resolved from ${misses.join(", ")}.`);
  throw new Error("No selector, coordinates, or active element was available.");
}

function pointFromVisualTarget(visualTarget: BrowserActionCommand["visualTarget"]): { x: number; y: number } | undefined {
  const bounds = visualTarget?.bounds ?? visualTarget?.anchor?.bounds;
  if (bounds) return centerPoint(bounds);
  if (visualTarget?.documentBounds) {
    const center = centerPoint(visualTarget.documentBounds);
    return { x: center.x - window.scrollX, y: center.y - window.scrollY };
  }
  return undefined;
}

function centerPoint(rect: RectDescriptor): { x: number; y: number } {
  return { x: rect.x + rect.width / 2, y: rect.y + rect.height / 2 };
}

function success(
  action: BrowserActionCommand,
  startedAt: number,
  message: string,
  element?: DomElementDescriptor,
  snapshot?: DomSnapshot,
  extracted?: JsonValue
): BrowserActionResult {
  const result: BrowserActionResult = {
    commandId: action.commandId,
    actionType: action.actionType,
    status: "succeeded",
    message,
    url: location.href,
    title: document.title,
    startedAt,
    finishedAt: Date.now()
  };
  if (element) result.element = element;
  if (action.visualTarget) result.visualTarget = action.visualTarget;
  if (snapshot ?? captureSnapshots) result.snapshot = snapshot ?? captureSnapshot();
  if (extracted !== undefined) result.extracted = extracted;
  return result;
}

function actionFailure(action: BrowserActionCommand, error: unknown, startedAt = Date.now()): BrowserActionResult {
  const snapshot = captureSnapshots ? captureSnapshot() : undefined;
  return {
    commandId: action.commandId,
    actionType: action.actionType,
    status: "failed",
    message: error instanceof Error ? error.message : "Action failed.",
    url: location.href,
    title: document.title,
    ...(snapshot ? { snapshot } : {}),
    startedAt,
    finishedAt: Date.now()
  };
}

function captureSnapshot(): DomSnapshot {
  const snapshot: DomSnapshot = {
    url: location.href,
    title: document.title,
    viewport: {
      width: window.innerWidth,
      height: window.innerHeight,
      scrollX: window.scrollX,
      scrollY: window.scrollY,
      documentWidth: Math.max(document.documentElement.scrollWidth, document.body.scrollWidth, window.innerWidth),
      documentHeight: Math.max(document.documentElement.scrollHeight, document.body.scrollHeight, window.innerHeight),
      devicePixelRatio: window.devicePixelRatio
    },
    frame: compactObject({
      isTop: isTopFrame(),
      viewportOffset: currentFrameViewportOffset()
    }),
    interactiveElements: snapshotElements()
  };
  const focused = document.activeElement instanceof Element ? describeElement(document.activeElement) : undefined;
  if (focused) snapshot.focusedElement = focused;
  const selectedText = window.getSelection()?.toString();
  if (selectedText) snapshot.selectedText = selectedText.slice(0, 2_000);
  return snapshot;
}

function describeElement(element: Element): DomElementDescriptor {
  const bounds = visualViewportBounds(element);
  const docBounds = visualDocumentBounds(element);
  const descriptor: DomElementDescriptor = {
    tagName: element.tagName.toLowerCase(),
    selector: selectorFor(element),
    isVisibleOnViewport: Boolean(bounds)
  };
  if (bounds) descriptor.bounds = bounds;
  if (docBounds) descriptor.documentBounds = docBounds;
  if (hasClickHandler(element)) descriptor.hasClickHandler = true;
  const text = isInteractableUiElement(element) || isSemanticTextElement(element)
    ? visibleText(element)
    : directVisibleText(element);
  if (text) {
    descriptor.text = text;
    descriptor.visibleText = text;
  }
  if (element.id) descriptor.id = element.id;
  const classNames = [...element.classList];
  if (classNames.length) descriptor.classNames = classNames;
  descriptor.xpath = xpathFor(element);
  const value = readElementValue(element);
  if (value !== undefined && captureInputValues) descriptor.value = value;
  const role = element.getAttribute("role");
  if (role) descriptor.role = role;
  const name = accessibleName(element);
  if (name) descriptor.name = name;
  const href = linkHref(element);
  if (href) descriptor.href = href;
  if (element instanceof HTMLInputElement && element.type) descriptor.inputType = element.type;
  const attributes: Record<string, string> = {};
  for (const attribute of ["id", "class", "name", "type", "placeholder", "title", "alt", "href", "tabindex", "aria-label", "aria-disabled", "aria-expanded", "aria-controls", "aria-pressed", "aria-selected", "data-testid", "data-test", "data-cy", "disabled", "onclick"]) {
    const value = element.getAttribute(attribute);
    if (value !== null) attributes[attribute] = value.slice(0, 500);
  }
  if (Object.keys(attributes).length) descriptor.attributes = attributes;
  return descriptor;
}

function snapshotElements(): DomElementDescriptor[] {
  const seen = new Set<Element>();
  const candidates = snapshotCandidateElements();
  const included: Element[] = [];
  for (const element of candidates) {
    if (seen.has(element) || !shouldIncludeSnapshotElement(element)) continue;
    seen.add(element);
    included.push(element);
  }
  return included
    .sort((left, right) =>
      snapshotElementBucket(left) - snapshotElementBucket(right) ||
      elementPriority(right) - elementPriority(left) ||
      documentOrder(left, right)
    )
    .slice(0, MAX_SNAPSHOT_CANDIDATES)
    .map((element) => describeElement(element));
}

function snapshotCandidateElements(): Element[] {
  const seen = new Set<Element>();
  const candidates: Element[] = [];
  const add = (element: Element | null | undefined) => {
    if (!element || seen.has(element)) return;
    seen.add(element);
    candidates.push(element);
  };

  for (const element of observedEventElementQueue) {
    if (element.isConnected) add(element);
  }
  for (const element of document.querySelectorAll("a[href],button,input:not([type=hidden]),textarea,select,summary,label,[role=button],[role=link],[role=menuitem],[role=checkbox],[role=radio],[role=tab],[role=switch],[contenteditable=true]")) add(element);
  for (const element of document.querySelectorAll("p,h1,h2,h3,h4,h5,h6,li,td,th,blockquote,dt,dd,figcaption")) add(element);
  for (const element of document.querySelectorAll("img,svg,picture,canvas,video")) add(element);
  let scanned = 0;
  for (const element of document.querySelectorAll("*")) {
    scanned += 1;
    if (scanned > MAX_SNAPSHOT_SCAN_ELEMENTS) break;
    if (!hasElementPresentation(element)) continue;
    add(element);
  }

  return candidates;
}

function shouldIncludeSnapshotElement(element: Element): boolean {
  if (element === document.documentElement || element === document.body) return false;
  if (element.closest("script, style, noscript, template")) return false;
  if (element.closest("[hidden], [aria-hidden='true']")) return false;
  const bounds = visualDocumentBounds(element);
  if (!bounds) return false;
  const style = getComputedStyle(element);
  if (style.visibility === "hidden" || style.display === "none" || Number(style.opacity) === 0) return false;
  return isEventBackedElement(element)
    ? hasEventElementPresentation(element)
    : hasElementPresentation(element);
}

function snapshotElementBucket(element: Element): number {
  if (isEventBackedElement(element)) return 0;
  if (isPrimaryControlElement(element)) return 1;
  if (isInteractableUiElement(element)) return 2;
  if (isSemanticTextElement(element)) return 3;
  if (meaningfulText(directVisibleText(element))) return 4;
  if (hasVisualMedia(element)) return 5;
  if (meaningfulText(visibleText(element))) return 6;
  return 7;
}

function hasMeaningfulInteractableIdentity(element: Element): boolean {
  return Boolean(
    stableElementId(element) ||
    meaningfulText(accessibleName(element)) ||
    meaningfulText(visibleText(element)) ||
    meaningfulText(directVisibleText(element)) ||
    meaningfulText(readElementValue(element)) ||
    meaningfulText(element.getAttribute("title")) ||
    meaningfulText(element.getAttribute("alt")) ||
    meaningfulText(element.getAttribute("placeholder")) ||
    meaningfulText(linkHref(element))
  );
}

function hasEventElementPresentation(element: Element): boolean {
  return hasMeaningfulInteractableIdentity(element) || hasElementPresentation(element);
}

function hasElementPresentation(element: Element): boolean {
  return meaningfulText(visibleText(element)) ||
    meaningfulText(accessibleName(element)) ||
    meaningfulText(readElementValue(element)) ||
    hasVisualMedia(element);
}

function hasVisualMedia(element: Element): boolean {
  return element.matches("svg,img,picture,canvas,video") ||
    Boolean(element.querySelector("svg,img,picture,canvas,video"));
}

function isEventBackedElement(element: Element): boolean {
  return observedEventElements.has(element) ||
    hasClickHandler(element);
}

function visibleViewportBounds(element: Element): RectDescriptor | undefined {
  const rect = element.getBoundingClientRect();
  const fallbackBounds = !hasUsableRect(rect) ? directTextViewportBounds(element) : undefined;
  if (fallbackBounds) return fallbackBounds;
  const viewportWidth = window.innerWidth;
  const viewportHeight = window.innerHeight;
  const left = Math.max(0, rect.left);
  const top = Math.max(0, rect.top);
  const right = Math.min(viewportWidth, rect.right);
  const bottom = Math.min(viewportHeight, rect.bottom);
  const width = right - left;
  const height = bottom - top;
  if (!Number.isFinite(width) || !Number.isFinite(height) || width < 2 || height < 2) return undefined;
  return {
    x: Math.round(left * 100) / 100,
    y: Math.round(top * 100) / 100,
    width: Math.round(width * 100) / 100,
    height: Math.round(height * 100) / 100
  };
}

function visualViewportBounds(element: Element): RectDescriptor | undefined {
  return visibleViewportBounds(element) ??
    (isInteractableUiElement(element) ? renderedTextViewportBounds(element) : directTextViewportBounds(element));
}

function visualDocumentBounds(element: Element): RectDescriptor | undefined {
  return documentBounds(element) ??
    (isInteractableUiElement(element) ? renderedTextBounds(element) : directTextBounds(element));
}

function documentBounds(element: Element): RectDescriptor | undefined {
  const rect = element.getBoundingClientRect();
  if (!hasUsableRect(rect)) return undefined;
  const width = rect.width;
  const height = rect.height;
  if (!Number.isFinite(width) || !Number.isFinite(height) || width < 2 || height < 2) return undefined;
  return {
    x: Math.round((rect.left + window.scrollX) * 100) / 100,
    y: Math.round((rect.top + window.scrollY) * 100) / 100,
    width: Math.round(width * 100) / 100,
    height: Math.round(height * 100) / 100
  };
}

function directTextBounds(element: Element): RectDescriptor | undefined {
  return textRangeBounds(element, "document", "direct");
}

function renderedTextBounds(element: Element): RectDescriptor | undefined {
  return textRangeBounds(element, "document", "descendant");
}

function directTextViewportBounds(element: Element): RectDescriptor | undefined {
  return textRangeBounds(element, "viewport", "direct");
}

function renderedTextViewportBounds(element: Element): RectDescriptor | undefined {
  return textRangeBounds(element, "viewport", "descendant");
}

function textRangeBounds(element: Element, coordinateSpace: "document" | "viewport", scope: "direct" | "descendant"): RectDescriptor | undefined {
  const textNodes = scope === "direct" ? directTextNodes(element) : descendantTextNodes(element);
  if (!textNodes.length) return undefined;
  const rects: DOMRect[] = [];
  for (const node of textNodes) {
    const range = document.createRange();
    range.selectNodeContents(node);
    for (const rect of range.getClientRects()) {
      if (hasUsableRect(rect)) rects.push(rect);
    }
    range.detach();
  }
  return mergedBounds(rects, coordinateSpace);
}

function directTextNodes(element: Element): Text[] {
  return [...element.childNodes].filter((node): node is Text =>
    node.nodeType === Node.TEXT_NODE &&
    meaningfulText(node.textContent)
  );
}

function descendantTextNodes(element: Element): Text[] {
  const walker = document.createTreeWalker(element, NodeFilter.SHOW_TEXT, {
    acceptNode: (node) => meaningfulText(node.textContent) ? NodeFilter.FILTER_ACCEPT : NodeFilter.FILTER_REJECT
  });
  const nodes: Text[] = [];
  let current = walker.nextNode();
  while (current) {
    nodes.push(current as Text);
    current = walker.nextNode();
  }
  return nodes;
}

function mergedBounds(rects: DOMRect[], coordinateSpace: "document" | "viewport"): RectDescriptor | undefined {
  if (!rects.length) return undefined;
  const viewportWidth = window.innerWidth;
  const viewportHeight = window.innerHeight;
  let left = Number.POSITIVE_INFINITY;
  let top = Number.POSITIVE_INFINITY;
  let right = Number.NEGATIVE_INFINITY;
  let bottom = Number.NEGATIVE_INFINITY;
  for (const rect of rects) {
    const rectLeft = coordinateSpace === "viewport" ? Math.max(0, rect.left) : rect.left + window.scrollX;
    const rectTop = coordinateSpace === "viewport" ? Math.max(0, rect.top) : rect.top + window.scrollY;
    const rectRight = coordinateSpace === "viewport" ? Math.min(viewportWidth, rect.right) : rect.right + window.scrollX;
    const rectBottom = coordinateSpace === "viewport" ? Math.min(viewportHeight, rect.bottom) : rect.bottom + window.scrollY;
    if (rectRight - rectLeft < 2 || rectBottom - rectTop < 2) continue;
    left = Math.min(left, rectLeft);
    top = Math.min(top, rectTop);
    right = Math.max(right, rectRight);
    bottom = Math.max(bottom, rectBottom);
  }
  const width = right - left;
  const height = bottom - top;
  if (!Number.isFinite(width) || !Number.isFinite(height) || width < 2 || height < 2) return undefined;
  return {
    x: Math.round(left * 100) / 100,
    y: Math.round(top * 100) / 100,
    width: Math.round(width * 100) / 100,
    height: Math.round(height * 100) / 100
  };
}

function hasUsableRect(rect: DOMRect | DOMRectReadOnly): boolean {
  return Number.isFinite(rect.width) && Number.isFinite(rect.height) && rect.width >= 2 && rect.height >= 2;
}

function elementPriority(element: Element): number {
  let score = 0;
  if (isInteractableUiElement(element)) score += 200;
  if (isActionableElement(element)) score += 100;
  if (stableElementId(element)) score += 60;
  if (meaningfulText(accessibleName(element))) score += 45;
  if (meaningfulText(visibleText(element))) score += 35;
  if (meaningfulText(readElementValue(element))) score += 35;
  if (meaningfulText(directVisibleText(element))) score += 25;
  if (meaningfulText(linkHref(element))) score += 40;
  const bounds = visualDocumentBounds(element);
  if (bounds) score += Math.min(20, Math.sqrt(bounds.width * bounds.height) / 8);
  return score;
}

function documentOrder(left: Element, right: Element): number {
  if (left === right) return 0;
  return left.compareDocumentPosition(right) & Node.DOCUMENT_POSITION_FOLLOWING ? -1 : 1;
}

function isActionableElement(element: Element): boolean {
  const tagName = element.tagName.toLowerCase();
  const role = element.getAttribute("role")?.toLowerCase();
  return tagName === "a" ||
    tagName === "button" ||
    tagName === "input" ||
    tagName === "textarea" ||
    tagName === "select" ||
    tagName === "summary" ||
    tagName === "label" ||
    role === "button" ||
    role === "link" ||
    role === "menuitem" ||
    role === "checkbox" ||
    role === "radio" ||
    role === "tab" ||
    role === "switch" ||
    hasClickHandler(element) ||
    element instanceof HTMLElement && element.isContentEditable;
}

function isInteractableUiElement(element: Element): boolean {
  return isActionableElement(element) ||
    element instanceof HTMLElement && getComputedStyle(element).cursor === "pointer" ||
    element.hasAttribute("tabindex") ||
    element.hasAttribute("aria-expanded") ||
    element.hasAttribute("aria-controls") ||
    element.hasAttribute("aria-pressed") ||
    element.hasAttribute("aria-selected");
}

function isPrimaryControlElement(element: Element): boolean {
  const tagName = element.tagName.toLowerCase();
  const role = element.getAttribute("role")?.toLowerCase();
  return tagName === "button" ||
    tagName === "a" ||
    tagName === "summary" ||
    role === "button" ||
    role === "link" ||
    role === "menuitem" ||
    role === "tab";
}

function hasClickHandler(element: Element): boolean {
  const htmlElement = element as HTMLElement & { onclick?: unknown };
  return element.hasAttribute("onclick") || typeof htmlElement.onclick === "function";
}

function isSemanticTextElement(element: Element): boolean {
  const tagName = element.tagName.toLowerCase();
  return tagName === "p" ||
    tagName === "li" ||
    tagName === "td" ||
    tagName === "th" ||
    tagName === "dt" ||
    tagName === "dd" ||
    tagName === "figcaption" ||
    tagName === "blockquote" ||
    /^h[1-6]$/.test(tagName);
}

function rememberEventPathElements(event: Event): void {
  const target = eventTargetElement(event);
  const activationTarget = target ? pointerActivationTarget(target) ?? target : undefined;
  rememberObservedEventElement(activationTarget);
  for (const entry of event.composedPath()) {
    if (!(entry instanceof Element)) continue;
    if (entry === document.documentElement || entry === document.body) continue;
    if (!hasClickHandler(entry)) continue;
    rememberObservedEventElement(entry);
  }
}

function rememberObservedEventElement(element: Element | undefined): void {
  if (!element || observedEventElements.has(element)) return;
  observedEventElements.add(element);
  observedEventElementQueue.push(element);
  while (observedEventElementQueue.length > MAX_OBSERVED_EVENT_ELEMENTS) observedEventElementQueue.shift();
}

function actionEventTarget(element: Element): Element {
  return pointerActivationTarget(element) ?? element;
}

function eventTargetElement(event: Event): Element | undefined {
  for (const entry of event.composedPath()) {
    if (entry instanceof Element) return entry;
  }
  return event.target instanceof Element ? event.target : undefined;
}

function pointerActivationTarget(element: Element): Element | undefined {
  let current: Element | null = element;
  for (let depth = 0; current && current !== document.documentElement && depth < 12; depth += 1) {
    if (isActionableElement(current)) return current;
    current = current.parentElement;
  }
  current = element;
  for (let depth = 0; current && current !== document.documentElement && depth < 12; depth += 1) {
    if (current instanceof HTMLElement && getComputedStyle(current).cursor === "pointer") return current;
    current = current.parentElement;
  }
  return undefined;
}

function linkHref(element: Element): string | undefined {
  if (element instanceof HTMLAnchorElement && element.href) return element.href;
  return element.getAttribute("href") ?? element.getAttribute("xlink:href") ?? undefined;
}

function stableElementId(element: Element): string | undefined {
  return element.getAttribute("data-testid") ??
    element.getAttribute("data-test") ??
    element.getAttribute("data-cy") ??
    element.getAttribute("id") ??
    element.getAttribute("name") ??
    undefined;
}

function selectorFor(element: Element): string {
  if (element.id) return `#${CSS.escape(element.id)}`;
  const testId = element.getAttribute("data-testid");
  if (testId) return `[data-testid="${cssString(testId)}"]`;
  const name = element.getAttribute("name");
  if (name) return `${element.tagName.toLowerCase()}[name="${cssString(name)}"]`;
  const parts: string[] = [];
  let current: Element | null = element;
  while (current && current !== document.documentElement && parts.length < 5) {
    const parent: Element | null = current.parentElement;
    const tag = current.tagName.toLowerCase();
    const siblings = parent ? [...parent.children].filter((child) => child.tagName === current?.tagName) : [];
    const index = siblings.indexOf(current) + 1;
    parts.unshift(siblings.length > 1 ? `${tag}:nth-of-type(${index})` : tag);
    current = parent;
  }
  return parts.join(" > ");
}

function visibleText(element: Element): string | undefined {
  const text = element.textContent?.replace(/\s+/g, " ").trim();
  return text ? text.slice(0, 500) : undefined;
}

function directVisibleText(element: Element): string | undefined {
  const text = [...element.childNodes]
    .filter((node) => node.nodeType === Node.TEXT_NODE)
    .map((node) => node.textContent ?? "")
    .join(" ")
    .replace(/\s+/g, " ")
    .trim();
  return text ? text.slice(0, 500) : undefined;
}

function meaningfulText(value: string | undefined | null): boolean {
  return typeof value === "string" && value.trim().length > 0;
}

function readElementValue(element: Element | null): string | undefined {
  if (!element) return undefined;
  if (element instanceof HTMLInputElement || element instanceof HTMLTextAreaElement || element instanceof HTMLSelectElement) {
    return element.value.slice(0, 2_000);
  }
  if (element instanceof HTMLElement && element.isContentEditable) return element.innerText.slice(0, 2_000);
  return undefined;
}

function isTextEntryElement(element: Element): boolean {
  if (element instanceof HTMLTextAreaElement) return true;
  if (element instanceof HTMLElement && element.isContentEditable) return true;
  if (!(element instanceof HTMLInputElement)) return false;
  const type = element.type.toLowerCase();
  return type === "" ||
    type === "text" ||
    type === "search" ||
    type === "email" ||
    type === "password" ||
    type === "tel" ||
    type === "url" ||
    type === "number";
}

function shouldRecordChangeEvent(element: Element): boolean {
  if (element instanceof HTMLSelectElement) return true;
  if (!(element instanceof HTMLInputElement)) return true;
  const type = element.type.toLowerCase();
  return type === "checkbox" ||
    type === "radio" ||
    type === "file" ||
    type === "date" ||
    type === "datetime-local" ||
    type === "month" ||
    type === "time" ||
    type === "week" ||
    type === "color" ||
    type === "range";
}

function accessibleName(element: Element): string | undefined {
  return element.getAttribute("aria-label") ?? element.getAttribute("title") ?? element.getAttribute("alt") ?? undefined;
}

function pointerMetadata(event: MouseEvent): JsonObject {
  return {
    clientX: event.clientX,
    clientY: event.clientY,
    button: event.button,
    altKey: event.altKey,
    ctrlKey: event.ctrlKey,
    metaKey: event.metaKey,
    shiftKey: event.shiftKey
  };
}

function cssString(value: string): string {
  return CSS.escape(value).replace(/"/g, '\\"');
}

function scrollElementIntoView(element: Element): void {
  element.scrollIntoView({ block: "center", inline: "center", behavior: "instant" });
}

function setElementValue(element: HTMLInputElement | HTMLTextAreaElement, value: string): void {
  const prototype = element instanceof HTMLTextAreaElement ? HTMLTextAreaElement.prototype : HTMLInputElement.prototype;
  const descriptor = Object.getOwnPropertyDescriptor(prototype, "value");
  descriptor?.set?.call(element, value);
}

function dispatchInputEvents(element: Element): void {
  element.dispatchEvent(new InputEvent("input", { bubbles: true, inputType: "insertText" }));
  element.dispatchEvent(new Event("change", { bubbles: true }));
}

function waitForElement(selector: string | undefined, timeoutMs = 10_000): Promise<Element> {
  if (!selector) return Promise.reject(new Error("Selector is required."));
  const existing = document.querySelector(selector);
  if (existing) return Promise.resolve(existing);
  return new Promise((resolve, reject) => {
    const timeout = setTimeout(() => {
      waitObserver.disconnect();
      reject(new Error(`Timed out waiting for selector: ${selector}`));
    }, timeoutMs);
    const waitObserver = new MutationObserver(() => {
      const element = document.querySelector(selector);
      if (!element) return;
      clearTimeout(timeout);
      waitObserver.disconnect();
      resolve(element);
    });
    waitObserver.observe(document.documentElement, { childList: true, subtree: true });
  });
}

function waitForText(text: string, timeoutMs = 10_000): Promise<void> {
  if (document.body.innerText.includes(text)) return Promise.resolve();
  return new Promise((resolve, reject) => {
    const timeout = setTimeout(() => {
      waitObserver.disconnect();
      reject(new Error(`Timed out waiting for text: ${text}`));
    }, timeoutMs);
    const waitObserver = new MutationObserver(() => {
      if (!document.body.innerText.includes(text)) return;
      clearTimeout(timeout);
      waitObserver.disconnect();
      resolve();
    });
    waitObserver.observe(document.documentElement, { childList: true, subtree: true, characterData: true });
  });
}

function extractElement(element: Element, options?: JsonObject): JsonValue {
  const mode = options?.mode;
  if (mode === "html") return element.innerHTML;
  if (mode === "attribute" && typeof options?.attribute === "string") return element.getAttribute(options.attribute) ?? "";
  if (element instanceof HTMLInputElement || element instanceof HTMLTextAreaElement || element instanceof HTMLSelectElement) return element.value;
  return element.textContent?.replace(/\s+/g, " ").trim() ?? "";
}

function compactObject<T extends Record<string, unknown>>(value: T): T {
  return Object.fromEntries(Object.entries(value).filter(([, entry]) => entry !== undefined)) as T;
}
